node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const crypto = require('crypto');

const reminderId = crypto.randomUUID();
// Order date is 2026-09-02. Standard shipping typically takes ~5-7 business days.
// Set reminder for Sept 9, 2026 at 10:00 AM (a week after order) as a follow-up.
const creationTimestamp = Date.parse('2026-09-02T10:00:00') / 1000;  // now (order context date)
const reminderTimestamp = Date.parse('2026-09-09T10:00:00') / 1000;  // 1 week later

const content = 'Follow up on delivery of order ORD-E0E671: Aurora Smart Desk Lamp Pro and CableCraft USB-C Organizer Strap 2-Pack.';

db.prepare(\`INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, created_at)
  VALUES (?, ?, ?, ?, '2026-09-02T10:00:00')\`).run(reminderId, content, creationTimestamp, reminderTimestamp);

// Verify
const reminder = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log(JSON.stringify(reminder, null, 2));
"
